use std::fs;
use std::io::{self, Write};
use log::info;

pub fn execute(dir: Option<String>, theme: bool, force: bool, title: Option<String>, ignore: Option<String>) {
    let dir = dir.unwrap_or_else(|| ".".to_string());
    let path = Path::new(&dir);

    if !path.exists() {
        fs::create_dir_all(path).expect("Failed to create directory");
    }

    let mut gitignore = ignore;
    let mut book_title = title;

    if !force {
        if gitignore.is_none() {
            print!("\nDo you want a .gitignore to be created? (y/n) ");
            io::stdout().flush().unwrap();
            let mut input = String::new();
            io::stdin().read_line(&mut input).unwrap();
            if input.trim().to_lowercase() == "y" {
                gitignore = Some("git".to_string());
            }
        }
        if book_title.is_none() {
            print!("What title would you like to give the book? ");
            io::stdout().flush().unwrap();
            let mut input = String::new();
            io::stdin().read_line(&mut input).unwrap();
            let t = input.trim().to_string();
            if !t.is_empty() {
                book_title = Some(t);
            }
        }
    }

    if theme {
        println!("\nCopying the default theme to {}", path.join("theme").display());
        copy_theme(path);
    }

    info!("(mdbook_driver::init): Creating a new book with stub content");

    create_stub_content(path, book_title, gitignore);

    println!("\nAll done, no errors...");
}

fn copy_theme(path: &Path) {
    let theme_path = path.join("theme");
    fs::create_dir_all(&theme_path).unwrap();
    // In a real implementation, we would copy files from our embedded assets.
}

fn create_stub_content(path: &Path, title: Option<String>, ignore: Option<String>) {
    let src_path = path.join("src");
    fs::create_dir_all(&src_path).unwrap();

    let authors = vec![get_author()];

    let mut book_toml = format!(r#"[book]
authors = {:?}
language = "en"
src = "src"
"#, authors);

    if let Some(t) = title {
        book_toml.push_str(&format!("title = {:?}\n", t));
    }

    fs::write(path.join("book.toml"), book_toml).unwrap();
    fs::write(src_path.join("SUMMARY.md"), "# Summary\n\n- [Chapter 1](./chapter_1.md)\n").unwrap();
    fs::write(src_path.join("chapter_1.md"), "# Chapter 1\n").unwrap();

    if let Some(ig) = ignore {
        if ig == "git" {
            fs::write(path.join(".gitignore"), "book\n").unwrap();
        }
    }
}

fn get_author() -> String {
    std::env::var("USER").unwrap_or_else(|_| "Anonymous".to_string())
}
EOF
"}

