{"command":"cat <<'EOF' > src/build.rs
use std::path::{Path, PathBuf};
use std::fs;
use crate::config::Config;
use crate::assets;
use log::info;
use pulldown_cmark::{Parser, Options, html};
use handlebars::Handlebars;
use serde_json::json;

pub fn execute(dir: Option<String>, dest_dir: Option<String>, open: bool) {
    let root = dir.map(PathBuf::from).unwrap_or_else(|| std::env::current_dir().unwrap());
    let config = Config::from_file(root.join("book.toml"));

    let src_dir = root.join(config.book.src.as_deref().unwrap_or("src"));
    let build_dir = dest_dir.map(PathBuf::from).unwrap_or_else(|| {
        if let Some(output) = &config.output {
            if let Some(html) = &output.html {
                if let Some(bd) = &html.build_dir {
                    return root.join(bd);
                }
            }
        }
        root.join("book")
    });

    info!("(mdbook_driver::mdbook): Book building has started");
    info!("(mdbook_driver::mdbook): Running the html backend");

    if !build_dir.exists() {
        fs::create_dir_all(&build_dir).unwrap();
    }

    // 1. Copy assets
    let all_assets = assets::get_assets();
    for (path, bytes) in &all_assets {
        let dest = build_dir.join(path);
        if let Some(parent) = dest.parent() {
            fs::create_dir_all(parent).unwrap();
        }
        fs::write(dest, bytes).unwrap();
    }

    // Also copy FontAwesome
    // Wait, the assets are already organized in src/assets/theme and src/assets/FontAwesome
    // My assets::get_assets() returns paths relative to src/assets.
    // So "theme/..." and "FontAwesome/..."
    // But mdbook expects some files directly in the root of the book dir.
    // Let's fix that.
    for (path, bytes) in &all_assets {
        let dest;
        if path.starts_with("theme/") {
            dest = build_dir.join(&path[6..]);
        } else {
            dest = build_dir.join(path);
        }
        if let Some(parent) = dest.parent() {
            fs::create_dir_all(parent).unwrap();
        }
        fs::write(dest, bytes).unwrap();
    }

    // 2. Parse SUMMARY.md
    let summary_path = src_dir.join("SUMMARY.md");
    let summary_content = fs::read_to_string(summary_path).unwrap_or_default();
    let chapters = parse_summary(&summary_content);

    // 3. Render chapters
    let mut hb = Handlebars::new();
    let index_hbs = String::from_utf8_lossy(all_assets.get("theme/index.hbs").expect("Missing index.hbs")).to_string();
    hb.register_template_string("index", index_hbs).unwrap();

    let toc_html = render_toc(&chapters);

    for (i, chapter) in chapters.iter().enumerate() {
        let chapter_path = src_dir.join(&chapter.location);
        let content_md = fs::read_to_string(&chapter_path).unwrap_or_default();
        let mut options = Options::empty();
        options.insert(Options::ENABLE_TABLES);
        options.insert(Options::ENABLE_FOOTNOTES);
        let parser = Parser::new_ext(&content_md, options);
        let mut content_html = String::new();
        html::push_html(&mut content_html, parser);

        let dest_path = build_dir.join(&chapter.location).with_extension("html");
        if let Some(parent) = dest_path.parent() {
            fs::create_dir_all(parent).unwrap();
        }

        let context = json!({
            "language": config.book.language.as_deref().unwrap_or("en"),
            "title": format!("{} - {}", chapter.name, config.book.title.as_deref().unwrap_or("")),
            "content": content_html,
            "toc": toc_html,
            "path_to_root": "", // Simplified
            "default_theme": "light",
            "preferred_dark_theme": "navy",
            "book_title": config.book.title,
            "chapters": [], // Simplified
            "previous": if i > 0 { Some(json!({"link": chapters[i-1].location.replace(".md", ".html"), "name": chapters[i-1].name})) } else { None },
            "next": if i < chapters.len() - 1 { Some(json!({"link": chapters[i+1].location.replace(".md", ".html"), "name": chapters[i+1].name})) } else { None },
        });

        let rendered = hb.render("index", &context).unwrap();
        fs::write(&dest_path, rendered).unwrap();

        if i == 0 {
            // Also write index.html
            fs::write(build_dir.join("index.html"), hb.render("index", &context).unwrap()).unwrap();
        }
    }

    info!("(mdbook_html::html_handlebars::hbs_renderer): HTML book written to {:?}", build_dir);

    if open {
        opener::open(build_dir.join("index.html")).ok();
    }
}

pub struct Chapter {
    pub name: String,
    pub location: String,
}

fn parse_summary(summary_md: &str) -> Vec<Chapter> {
    let mut chapters = Vec::new();
    let parser = Parser::new(summary_md);
    let mut in_link = false;
    let mut current_name = String::new();
    let mut current_location = String::new();

    for event in parser {
        match event {
            pulldown_cmark::Event::Start(pulldown_cmark::Tag::Link(_, dest, _)) => {
                in_link = true;
                current_location = dest.to_string();
            }
            pulldown_cmark::Event::End(pulldown_cmark::Tag::Link(_, _, _)) => {
                in_link = false;
                chapters.push(Chapter {
                    name: current_name.clone(),
                    location: current_location.clone(),
                });
                current_name.clear();
            }
            pulldown_cmark::Event::Text(text) => {
                if in_link {
                    current_name.push_str(&text);
                }
            }
            _ => {}
        }
    }
    chapters
}

fn render_toc(chapters: &[Chapter]) -> String {
    let mut html = String::from("<ul class=\"chapter\">");
    for chapter in chapters {
        let link = chapter.location.replace(".md", ".html");
        html.push_str(&format!(r#"<li class="chapter-item expanded"><a href="{}">{}</a></li>"#, link, chapter.name));
    }
    html.push_str("</ul>");
    html
}
EOF
"}

